const p1 = document.getElementById('low-contrast-gray');
const p2 = document.getElementById('high-contrast-text');
const h1 = document.getElementById('high-contrast-large');
const btn = document.getElementById('high-contrast-button');
const c1 = getComputedStyle(p1).color;
const c2 = getComputedStyle(p2).color;
const ch1 = getComputedStyle(h1).color;
const cb = getComputedStyle(btn).color;
const bg1 = getComputedStyle(p1).backgroundColor;
const bgBody = getComputedStyle(document.body).backgroundColor;

const isYellow = (c) => c === 'rgb(255, 255, 0)';
const isBlack = (bg) => bg === 'rgb(0, 0, 0)';

return isYellow(c1) && isYellow(c2) && isYellow(ch1) && isYellow(cb) && isBlack(bg1) && isBlack(bgBody);

const img = document.getElementById('test-image');
const canvas = document.getElementById('test-canvas');
const video = document.getElementById('test-video');
const imgClean = !img.hasAttribute('style') && getComputedStyle(img).filter === 'none';
const canvasClean = !canvas.hasAttribute('style') && getComputedStyle(canvas).filter === 'none';
const videoClean = !video.hasAttribute('style') && getComputedStyle(video).filter === 'none';
return imgClean && canvasClean && videoClean;
